    def __init__(self, frontend_cycle_days, backend_cycle_days):
        self.f_frontend = 1.0 / frontend_cycle_days  # Frequency in deployments/day
        self.f_backend = 1.0 / backend_cycle_days
        self.beat_frequency = abs(self.f_frontend - self.f_backend)
        self.beat_period = 1.0 / self.beat_frequency if self.beat_frequency > 0 else float('inf')

    def calculate_interference_pattern(self, days=90):
        """Model the interference pattern between deployment cycles"""
        t = np.linspace(0, days, 1000)

        # Wave functions for each deployment cycle
        frontend_wave = np.cos(2 * np.pi * self.f_frontend * t)
        backend_wave = np.cos(2 * np.pi * self.f_backend * t)

        # Superposition creates the beat pattern
        interference = frontend_wave + backend_wave

        # Envelope of the beat pattern (risk amplitude)
        envelope = 2 * np.cos(np.pi * self.beat_frequency * t)

        return t, interference, envelope

    def find_critical_points(self):
        """Find when maximum interference (integration risk) occurs"""
        # Constructive interference at: t = n / beat_frequency
        # Destructive interference at: t = (n + 0.5) / beat_frequency

        critical_points = []
        for n in range(int(90 * self.beat_frequency) + 1):
            constructive_t = n / self.beat_frequency
            destructive_t = (n + 0.5) / self.beat_frequency

