class IntegrationStandingWave:
    def __init__(self, frontend_cycle, backend_cycle, api_contract_volatility=0.1):
        self.frontend_cycle = frontend_cycle
        self.backend_cycle = backend_cycle
        self.volatility = api_contract_volatility

