    def calculate_standing_wave(self, days=90):
        """Model the standing wave pattern of integration stability"""
        t = np.linspace(0, days, 1000)

        # Forward wave (frontend pushing changes)
        k_frontend = 2 * np.pi / self.frontend_cycle
        forward_wave = np.sin(k_frontend * t)

